<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$type=$_GET['type']??'operations';$rows=[];if($type==='projects'){$rows=$db->query("SELECT status,COUNT(*) total FROM client_projects GROUP BY status ORDER BY total DESC")->fetchAll();}elseif($type==='support'){$rows=$db->query("SELECT status,COUNT(*) total FROM support_tickets GROUP BY status ORDER BY total DESC")->fetchAll();}elseif($type==='clients'){$rows=$db->query("SELECT health,COUNT(*) total FROM client_success_profiles GROUP BY health ORDER BY total DESC")->fetchAll();}else{$rows=$db->query("SELECT DATE(created_at) day,COUNT(*) total FROM clients WHERE created_at>=DATE_SUB(CURDATE(),INTERVAL 30 DAY) GROUP BY DATE(created_at) ORDER BY day")->fetchAll();}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Report Center</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><h1 class="h3">Report Center</h1><div class="mb-3"><a href="?type=operations">Operations</a> · <a href="?type=projects">Projects</a> · <a href="?type=support">Support</a> · <a href="?type=clients">Client Health</a></div><table class="table table-bordered bg-white"><thead><tr><?php if($rows):foreach(array_keys($rows[0]) as $h):?><th><?=htmlspecialchars((string)$h)?></th><?php endforeach;endif;?></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php foreach($r as $v):?><td><?=htmlspecialchars((string)$v)?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></main></body></html>